func TestImportRuleSegmentObjects(t *testing.T) {
 for _, tc := range []struct { name, document string; keys []string; operator flipt.SegmentOperator }{
  {\"single\", \"testdata/import_rule_multiple_segments.yml\", []string{\"segment1\"}, flipt.SegmentOperator_OR_SEGMENT_OPERATOR},
