   var reader *strings.Reader
   if tc.document "'!= "" {
    data, err := os.ReadFile(tc.document); require.NoError(t, err)
    reader = strings.NewReader(string(data))
   } else {
    reader = strings.NewReader("flags:'"\\n- key: flag1\\n  name: flag1\\n  type: VARIANT_FLAG_TYPE\\n  enabled: true\\n  rules:\\n  - segment:\\n      keys: [segment1, segment2]\\n      operator: AND_SEGMENT_OPERATOR\\nsegments:\\n- key: segment1\\n  name: segment1\\n- key: segment2\\n  name: segment2\\n\")
